"""Manually scoped next twenty operations; no target-status oracle."""
def st(*v):return list(map(str,v))
def chain(names,colours,predicates,hyp):
    gs=[{'id':n,'ordered_inputs':[colours[i]],'output':colours[i+1],'arity':1,'carrier':'Declared '+colours[i],'coefficient_ring':'Exact Q, Q(i), or Q(sqrt5) as declared; real embedding only in the named Lean conditional','hypotheses':[hyp],'semantic_predicate':p} for i,(n,p) in enumerate(zip(names,predicates))]
    cs=[{'outer_operation':names[i+1],'input_slot':0,'inner_operation':names[i]} for i in range(2)]
    return gs,cs
S=[]
def spec(kind,cases,anchors,review,support,unpaid,names,colours,predicates,hyp,equations):
    gs,cs=chain(names,colours,predicates,hyp)
    S.append(dict(kind=kind,cases=cases,anchors=anchors,review=review,support=support,unpaid=unpaid,gens=gs,comps=cs,equations=equations))

